import*as z from"zod";import{createValidatorFn}from"../common/zod-tools.js";const allValidators={uId:z.string().min(3).max(30),hidden:z.boolean(),pinned:z.boolean(),friendlyLink:{name:z.string().min(1).max(300),link:z.string().min(1).max(700),icon:z.string().min(0).max(700),content:z.string().min(0).max(1500)},user:{nickname:z.string().min(1).max(300),password:z.string().min(1).max(300),synopsis:z.string().min(0).max(700),avatar:z.string().min(0).max(700),about:z.string().min(0).max(15e3)}},friendlyLinkAddValidator=z.object({name:allValidators.friendlyLink.name,link:allValidators.friendlyLink.link,icon:allValidators.friendlyLink.icon.optional(),content:allValidators.friendlyLink.content.optional(),hidden:allValidators.hidden});export const friendlyLinkAddValidatorFn=createValidatorFn(friendlyLinkAddValidator);const friendlyLinkUpdateValidator=z.object({uId:allValidators.uId,name:allValidators.friendlyLink.name.optional(),link:allValidators.friendlyLink.link.optional(),icon:allValidators.friendlyLink.icon.optional(),content:allValidators.friendlyLink.content.optional(),hidden:allValidators.hidden});export const friendlyLinkUpdateValidatorFn=createValidatorFn(friendlyLinkUpdateValidator);const userUpdateValidator=z.object({uId:allValidators.uId,nickname:allValidators.user.nickname.optional(),synopsis:allValidators.user.synopsis.optional(),avatar:allValidators.user.avatar.optional(),about:allValidators.user.about.optional()});export const userUpdateValidatorFn=createValidatorFn(userUpdateValidator);const userRegisterValidator=z.object({name:z.string().min(3).max(30),password:allValidators.user.password});export const userRegisterValidatorFn=createValidatorFn(userRegisterValidator);const noteAddValidator=z.object({title:z.string().min(0).max(300),content:z.string().min(1).max(15e3),hidden:allValidators.hidden,pinned:allValidators.pinned});export const noteAddValidatorFn=createValidatorFn(noteAddValidator);const noteUpdateValidator=z.object({uId:allValidators.uId,title:z.string().min(0).max(300).optional(),content:z.string().min(1).max(15e3).optional(),hidden:allValidators.hidden.optional(),pinned:allValidators.pinned.optional()});export const noteUpdateValidatorFn=createValidatorFn(noteUpdateValidator);